// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeHeart } from "@remotion/shapes";



export type BrokenHeartProps = Record<string, any>;

const BrokenHeart: React.FC<BrokenHeartProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 4,
  heartColor = "#ff2a5f",
  shatterForce = 1.2,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive sizing for the heart
  const heartHeight = height * 0.35;
  const { path, width: heartW, height: heartH } = useMemo(
    () => makeHeart({ height: heartHeight }),
    [heartHeight]
  );

  // Animation timing
  const breakFrame = 47;
  const isBroken = frame >= breakFrame;
  const timeBroken = Math.max(0, frame - breakFrame);

  // Heartbeat scale sequence (pumps twice before breaking)
  const scale = interpolate(
    frame,
    [10, 13, 16, 20, 24, 38, 41, 44, 47],
    [1, 1.15, 1, 1.1, 1, 1, 1.15, 1, 1.15],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // Freeze the scale at its peak when it shatters
  const finalScale = isBroken ? 1.15 : scale;

  // Physics and shatter calculations
  const breakProgress = spring({
    frame: timeBroken,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const explodeX = breakProgress * (width * 0.08);
  const explodeY = breakProgress * -(height * 0.04);
  const fallY = Math.pow(timeBroken, 2) * (height * 0.00015);

  const leftX = -explodeX * shatterForce;
  const leftY = explodeY * shatterForce + fallY;
  const leftRot = -breakProgress * 15 * shatterForce;

  const rightX = explodeX * shatterForce;
  const rightY = (explodeY + (height * 0.015)) * shatterForce + fallY;
  const rightRot = breakProgress * 18 * shatterForce;

  // Dynamic crack path points (jagged cut down the middle)
  const p1 = `${heartW / 2},0`;
  const p2 = `${heartW / 2 + heartW * 0.05},${heartH * 0.3}`;
  const p3 = `${heartW / 2 - heartW * 0.04},${heartH * 0.6}`;
  const p4 = `${heartW / 2 + heartW * 0.02},${heartH * 0.8}`;
  const p5 = `${heartW / 2},${heartH}`;

  const leftPoly = `0,0 ${p1} ${p2} ${p3} ${p4} ${p5} 0,${heartH}`;
  const rightPoly = `${heartW},0 ${p1} ${p2} ${p3} ${p4} ${p5} ${heartW},${heartH}`;

  // Shard properties for the explosion
  const shardData = useMemo(() => [
    { sizeRatio: 0.02, angle: -110, distRatio: 0.3, rotSpeed: 12, delay: 0, startRot: 45 },
    { sizeRatio: 0.015, angle: -70, distRatio: 0.25, rotSpeed: -15, delay: 2, startRot: 120 },
    { sizeRatio: 0.025, angle: -90, distRatio: 0.35, rotSpeed: 20, delay: 0, startRot: 15 },
    { sizeRatio: 0.01, angle: -40, distRatio: 0.2, rotSpeed: -10, delay: 1, startRot: -40 },
    { sizeRatio: 0.018, angle: -140, distRatio: 0.32, rotSpeed: 14, delay: 1, startRot: 80 },
    { sizeRatio: 0.012, angle: -100, distRatio: 0.22, rotSpeed: -25, delay: 3, startRot: 200 },
  ], []);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      <div style={{ 
        position: "relative", 
        width: heartW, 
        height: heartH, 
        transform: `scale(${finalScale})`,
        transition: "none"
      }}>
        
        {/* Unbroken Heart (Visible until breakFrame) */}
        {!isBroken && (
          <svg 
            width={heartW} 
            height={heartH} 
            viewBox={`0 0 ${heartW} ${heartH}`} 
            style={{ position: "absolute", top: 0, left: 0, overflow: "visible", transition: "none" }}
          >
            <path d={path} fill={heartColor} style={{ transition: "none" }} />
          </svg>
        )}

        {/* Broken Pieces (Visible after breakFrame) */}
        {isBroken && (
          <>
            {/* SVG Definitions for clipping masks */}
            <svg width={0} height={0} style={{ position: "absolute" }}>
              <defs>
                <clipPath id="left-crack">
                  <polygon points={leftPoly} />
                </clipPath>
                <clipPath id="right-crack">
                  <polygon points={rightPoly} />
                </clipPath>
              </defs>
            </svg>

            {/* Left Piece */}
            <div style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: heartW,
              height: heartH,
              transform: `translate(${leftX}px, ${leftY}px) rotate(${leftRot}deg)`,
              transformOrigin: `${heartW / 2}px ${heartH / 2}px`,
              transition: "none"
            }}>
              <svg width={heartW} height={heartH} viewBox={`0 0 ${heartW} ${heartH}`} style={{ overflow: "visible" }}>
                <path d={path} fill={heartColor} clipPath="url(#left-crack)" style={{ transition: "none" }} />
              </svg>
            </div>

            {/* Right Piece */}
            <div style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: heartW,
              height: heartH,
              transform: `translate(${rightX}px, ${rightY}px) rotate(${rightRot}deg)`,
              transformOrigin: `${heartW / 2}px ${heartH / 2}px`,
              transition: "none"
            }}>
              <svg width={heartW} height={heartH} viewBox={`0 0 ${heartW} ${heartH}`} style={{ overflow: "visible" }}>
                <path d={path} fill={heartColor} clipPath="url(#right-crack)" style={{ transition: "none" }} />
              </svg>
            </div>

            {/* Exploding Shards */}
            {shardData.map((shard, i) => {
              const shardProgress = spring({
                frame: Math.max(0, timeBroken - shard.delay),
                fps,
                config: { damping: 14, stiffness: 120 },
              });
              
              const size = width * shard.sizeRatio;
              const distance = width * shard.distRatio;
              const rad = (shard.angle * Math.PI) / 180;
              
              const sX = Math.cos(rad) * distance * shardProgress * shatterForce;
              const sY = Math.sin(rad) * distance * shardProgress * shatterForce + fallY;
              const sRot = shard.startRot + (Math.max(0, timeBroken - shard.delay) * shard.rotSpeed);

              const startX = heartW / 2;
              const startY = heartH * 0.4;

              return (
                <div key={i} style={{
                  position: "absolute",
                  top: startY - size / 2,
                  left: startX - size / 2,
                  width: size,
                  height: size,
                  transform: `translate(${sX}px, ${sY}px) rotate(${sRot}deg)`,
                  transformOrigin: "center",
                  transition: "none"
                }}>
                  <svg width={size} height={size} viewBox="0 0 100 100" style={{ overflow: "visible" }}>
                    <polygon points="50,0 100,80 0,100" fill={heartColor} style={{ transition: "none" }} />
                  </svg>
                </div>
              );
            })}
          </>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default BrokenHeart;